import sys

def convert_encoding(input_text, target_encoding):
    """Convert input text to target encoding"""
    try:
        return input_text.encode(target_encoding)
    except UnicodeError:
        print(f"Error converting to {target_encoding}")
        return None

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python encoding_converter.py <text> <encoding>")
        sys.exit(1)
    text = sys.argv[1]
    encoding = sys.argv[2]
    result = convert_encoding(text, encoding)
    if result:
        print(result.decode(encoding))

