import os

def normalize_path(path):
    return os.path.normpath(path)

routes = {
    '/home': 'index.html',
    '/user/:id': 'profile.html',
    '/static/*': 'assets/$1'
}

def match_route(path):
    for route in routes:
        if path.startswith(route):
            return routes[route]
    return '404.html'
